    "explanation": "(A): Genes have alleles. | (B): Turner syndrome is a chromosomal (not gene) defect. | (C): Female karyotype is 46,XX. | (D): Genes code for polypeptides/enzymes. | (E): Base pairing is A–T, G–C only.",
